import java.util.Scanner;

public class cf2 {

	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		sc.nextLine();
		int count=0;
		int flag=0;
		int max=0;
		int len=0;
		String str=sc.nextLine();
		for(int i=0;i<t;i++)
		{
			flag=0;
			len=0;
			if(str.charAt(i)=='_')
				continue;
			else if(str.charAt(i)=='(')
			{
				i++;
				while(i<t && str.charAt(i)!=')')
				{
					if(i<t && str.charAt(i)!='_' && str.charAt(i)!=')')
					{
						while(i<t && str.charAt(i)!='_' && str.charAt(i)!=')')
							i++;
						count++;
						i--;
					}
					i++;
				}
			}
			else
			{
				if(i<t && str.charAt(i)!='_' && str.charAt(i)!='(' && str.charAt(i)!=')')
				{
					while(i<t && str.charAt(i)!='_' && str.charAt(i)!='(' && str.charAt(i)!=')')
					{
						len++;
						i++;
					}
					if(len>=max)
						max=len;
				}
				i--;
			}
		}
		System.out.println(max+" "+count);
	}

}
